import api from './api';

export const clientTeamService = {
  // Asignar consultor a cliente
  assignConsultant: async (data) => {
    const response = await api.post('/client-team', data);
    return response.data;
  },

  // Obtener consultores de un cliente
  getClientConsultants: async (clientId) => {
    const response = await api.get(`/client-team/client/${clientId}`);
    return response.data;
  },

  // Obtener clientes de un consultor
  getConsultantClients: async (userId) => {
    const response = await api.get(`/client-team/consultant/${userId}`);
    return response.data;
  },

  // Obtener todos los consultores disponibles
  getAvailableConsultants: async () => {
    const response = await api.get('/client-team/consultants');
    return response.data;
  },

  // Actualizar rol de consultor
  updateConsultantRole: async (assignmentId, role) => {
    const response = await api.put(`/client-team/${assignmentId}/role`, { role });
    return response.data;
  },

  // Remover asignación
  removeAssignment: async (assignmentId) => {
    const response = await api.delete(`/client-team/${assignmentId}`);
    return response.data;
  },
};
